def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    by_color = {}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            y0 = min(y for y, x in cells)
            x0 = min(x for y, x in cells)
            shape = [(y - y0, x - x0) for y, x in cells]
            by_color.setdefault(color, []).append(shape)

    out = [[0] * w for _ in range(h)]
    for color_index, color in enumerate(sorted(by_color)):
        # Small shape goes in the upper position; large shape in the lower.
        shapes = sorted(by_color[color], key=len)
        xbase = 0 if color_index == 0 else 5
        for index, shape in enumerate(shapes):
            height = max(y for y, x in shape) + 1
            width = max(x for y, x in shape) + 1
            if index == 0:
                ybase = 6 - height       # bottom-align at row 5
            else:
                ybase = 10 - height      # bottom-align at row 9
            for dy, dx in shape:
                y, x = ybase + dy, xbase + dx
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
    return out
